package handlers

import (
	"net/http"
	"strings"

	"app/internal/httpx"
	"app/internal/logging"
	"app/templates/errorpage"
)

func (h *Handler) route(w http.ResponseWriter, r *http.Request) {
	if h.options(w, r) {
		return
	}
	h.mux.ServeHTTP(&routingErrorWriter{ResponseWriter: w, handler: h, request: r}, r)
}

// Only replace errors generated by ServeMux (which have no matched pattern).
// Keep its Allow header, redirects, path values and endpoint responses intact.
type routingErrorWriter struct {
	http.ResponseWriter
	handler  *Handler
	request  *http.Request
	replaced bool
}

func (w *routingErrorWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

func (w *routingErrorWriter) WriteHeader(status int) {
	if w.replaced {
		return
	}
	if w.request.Pattern != "" || (status != http.StatusNotFound && status != http.StatusMethodNotAllowed) {
		w.ResponseWriter.WriteHeader(status)
		return
	}
	key, message := "err.route_not_found", "route not found"
	if status == http.StatusMethodNotAllowed {
		if allow := w.Header().Get("Allow"); allow != "" && !strings.Contains(allow, "OPTIONS") {
			w.Header().Set("Allow", allow+", OPTIONS")
		}
		key, message = "err.method_not_allowed", "method not allowed"
	}
	w.replaced = true
	w.handler.writeRoutingError(w.ResponseWriter, w.request, status, key, message)
}

func (h *Handler) writeRoutingError(w http.ResponseWriter, r *http.Request, status int, key, message string) {
	if status == http.StatusNotFound {
		w.Header().Add("Vary", "Accept, Accept-Language")
		w.Header().Set("Cache-Control", "no-store")
		if httpx.Negotiate(r, "application/json; charset=utf-8", "text/html; charset=utf-8") == "text/html; charset=utf-8" {
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.WriteHeader(status)
			h.logger.Debug(message, logging.RequestArgs(r, status)...)
			if err := errorpage.NotFound(h.localize(r, key), h.links).Render(r.Context(), w); err != nil {
				h.logger.Error("failed to render not found page", logging.RequestArgs(r, status, "error", err)...)
			}
			return
		}
	}
	h.writeStatus(
		w,
		r,
		status,
		key,
		message,
	)
}

func (w *routingErrorWriter) Write(body []byte) (int, error) {
	if w.replaced {
		return len(body), nil
	}
	return w.ResponseWriter.Write(body)
}
